// Models Spring Cloud Gateway's runtime-mutable route table (RouteLocator/Repository).
package com.bank.gateway.demo;

import java.util.logging.*;

public class DynamicRoutingDemo {
    private static final Logger log = Logger.getLogger("DynamicRouting");
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setLevel(Level.ALL); h.setFormatter(new DrLogFormatter());
        log.addHandler(h); log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        RouteDefinitionRepository repo = new RouteDefinitionRepository();
        DynamicRouteEngine engine = new DynamicRouteEngine(repo);

        // Start: all payments to the OLD backend.
        repo.save(new RouteDefinition("payment-old", "/api/v1/payments", "payment-service-old", 100));
        repo.save(new RouteDefinition("account", "/api/v1/accounts", "account-service", 100));
        engine.refresh();

        log.info("=== Phase 1: all payments → OLD ===");
        for (int i = 0; i < 4; i++) route(engine, "/api/v1/payments/pay");

        // Runtime change: canary 25% of payments to the NEW backend.
        log.info("=== Phase 2: add weighted route, 25% payments → NEW ===");
        repo.save(new RouteDefinition("payment-old", "/api/v1/payments", "payment-service-old", 75));
        repo.save(new RouteDefinition("payment-new", "/api/v1/payments", "payment-service-new", 25));
        engine.refresh();
        for (int i = 0; i < 4; i++) route(engine, "/api/v1/payments/pay");

        // Runtime reroute: account service to a standby.
        log.info("=== Phase 3: reroute account → standby ===");
        repo.save(new RouteDefinition("account", "/api/v1/accounts", "account-service-standby", 100));
        engine.refresh();
        route(engine, "/api/v1/accounts/SAV2001");
    }

    private static void route(DynamicRouteEngine engine, String path) {
        String backend = engine.match(path);
        log.info(() -> path + " → " + backend);
    }
}

