class RouteDefinition {
    private final String id; private final String pathPrefix;
    private final String backend; private final int weight;
    RouteDefinition(String id, String pathPrefix, String backend, int weight) {
        this.id = id; this.pathPrefix = pathPrefix; this.backend = backend; this.weight = weight;
    }
    String getId() { return id; }
    String getPathPrefix() { return pathPrefix; }
    String getBackend() { return backend; }
    int getWeight() { return weight; }
}

// ─── Would be in route/RouteDefinitionRepository.java ───
class RouteDefinitionRepository {
    // keyed by id so save() both adds and updates (like InMemoryRouteDefinitionRepository)
    private final java.util.Map<String, RouteDefinition> defs = new java.util.LinkedHashMap<>();
    void save(RouteDefinition d) { defs.put(d.getId(), d); }
    void delete(String id) { defs.remove(id); }
    java.util.Collection<RouteDefinition> findAll() { return new java.util.ArrayList<>(defs.values()); }
}

