class DynamicRouteEngine {
    private static final Logger log = Logger.getLogger("DynamicRouting");
    private final RouteDefinitionRepository repo;
    private volatile java.util.List<RouteDefinition> compiled = java.util.List.of(); // cached route table
    private final java.util.Random rnd = new java.util.Random(42);

    DynamicRouteEngine(RouteDefinitionRepository repo) { this.repo = repo; }

    // Equivalent to publishing a RefreshRoutesEvent: rebuild the cached table.
    void refresh() {
        compiled = new java.util.ArrayList<>(repo.findAll());
        log.info(() -> "Routes refreshed: " + compiled.size() + " definitions");
    }

    // Match a path to a backend; apply weighted selection when multiple routes share a prefix.
    String match(String path) {
        java.util.List<RouteDefinition> candidates = new java.util.ArrayList<>();
        for (RouteDefinition d : compiled) if (path.startsWith(d.getPathPrefix())) candidates.add(d);
        if (candidates.isEmpty()) return "404-no-route";
        if (candidates.size() == 1) return candidates.get(0).getBackend();
        return weightedPick(candidates); // canary / blue-green split
    }

    private String weightedPick(java.util.List<RouteDefinition> candidates) {
        int total = candidates.stream().mapToInt(RouteDefinition::getWeight).sum();
        int roll = rnd.nextInt(total);
        int acc = 0;
        for (RouteDefinition d : candidates) {
            acc += d.getWeight();
            if (roll < acc) return d.getBackend();
        }
        return candidates.get(0).getBackend();
    }
}

